import limited_client as r,numpy as np
o=r.observe('corner2'); a=o['rgb'];d=o['depth_m'];K=o['intrinsic'];T=o['camera_to_world'];
for name,m in [('blue',(a[:,:,2]>a[:,:,0]*1.4)&(a[:,:,2]>a[:,:,1]*1.3)&(a[:,:,2]>50)&(a[:,:,0]<100)),('green',(a[:,:,1]>a[:,:,0]*1.5)&(a[:,:,1]>a[:,:,2]*1.5)&(a[:,:,1]>100))]:
 ys,xs=np.where(m); u=xs.mean();v=ys.mean(); z=np.median(d[ys,xs]); pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);pw=T@pc;print(name,'uv',u,v,'depth',z,'world',pw[:3])
PY

